import { describe, expect, it } from 'vitest';

import { creditPatterns, toolNames } from './patterns.ts';

const samples: [id: string, hit: string, miss: string][] = [
  [
    'co-authored-by',
    'Co-Authored-By: Some Tool <tool@example.com>',
    'Drop the `Co-Authored-By` trailer before you push',
  ],
  ['generated-line', 'Generated with a helper script', 'Docs are generated by the build'],
  ['session-trailer', 'Claude-Session: 0123abcd', 'Session: 0123abcd'],
  [
    'generated-link',
    'Generated with [Some Tool](https://example.com)',
    'Generated with protoc, do not edit',
  ],
  ['generated-tool', 'This file was generated by Codex', 'Code generated by protoc-gen-go'],
  ['built-with-tool', 'Built with Cursor', 'Built with TypeScript and Vitest'],
  ['session-link', 'See https://claude.ai/code/session_0123', 'See https://example.com/code/1'],
];

function pattern(id: string): RegExp {
  const found = creditPatterns.find((candidate) => candidate.id === id);
  if (found === undefined) {
    throw new Error(`No pattern with id ${id}`);
  }
  return found.regex;
}

describe('creditPatterns', () => {
  it('has a sample for every pattern, and unique ids', () => {
    const ids = creditPatterns.map((candidate) => candidate.id);

    expect(samples.map(([id]) => id)).toEqual(ids);
    expect(new Set(ids).size).toBe(ids.length);
  });

  it.each(samples)('%s matches %j', (id, hit) => {
    expect(pattern(id).test(hit)).toBe(true);
  });

  it.each(samples)('%s does not match ordinary text %j', (id, _hit, miss) => {
    expect(pattern(id).test(miss)).toBe(false);
  });

  it('never matches across calls because of regex state', () => {
    expect(creditPatterns.some((candidate) => candidate.regex.global)).toBe(false);
  });

  it.each(toolNames)('generated-tool and built-with-tool match the tool name %s', (name) => {
    expect(pattern('generated-tool').test(`generated using ${name}`)).toBe(true);
    expect(pattern('built-with-tool').test(`Written by ${name}.`)).toBe(true);
  });

  it.each([
    'https://chatgpt.com/codex/tasks/task_1',
    'https://cursor.com/agents?id=1',
    'https://app.devin.ai/sessions/1',
  ])('session-link matches %s', (link) => {
    expect(pattern('session-link').test(link)).toBe(true);
  });

  it.each([
    'rows created by cursor iteration',
    'Built with care',
    'Generated by the release workflow',
    'made with Geminid meteor data',
  ])('no content pattern matches the product text %j', (text) => {
    const hits = creditPatterns
      .filter((candidate) => candidate.scopes.includes('diff'))
      .filter((candidate) => candidate.regex.test(text));

    expect(hits).toEqual([]);
  });
});
